int bsearch(const int a[], int n, int target) {
  int lo = 0, hi = n - 1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) / 2;   // avoids (lo + hi) overflow
    if (a[mid] == target) return mid;
    if (a[mid] < target) lo = mid + 1; else hi = mid - 1;
  }
  return -1;
}

int lower_bound(const int a[], int n, int x) {
  int lo = 0, hi = n;          // half-open [lo, hi)
  while (lo < hi) { int m = lo + (hi - lo) / 2;
    if (a[m] < x) lo = m + 1; else hi = m; }
  return lo;
}

int bs(const int a[], int lo, int hi, int x) {
  if (lo > hi) return -1;
  int mid = lo + (hi - lo) / 2;
  if (a[mid] == x) return mid;
  return a[mid] < x ? bs(a, mid + 1, hi, x) : bs(a, lo, mid - 1, x);
}
